import React, { useState, useEffect } from 'react';
import { useDataLoader } from '../../data/loaders';
import CharacterNetwork from '../../components/CharacterNetwork';
import CharacterDetail from '../../components/CharacterNetwork/CharacterDetail';

const CharacterNetworkPage: React.FC = () => {
  const [characterData, setCharacterData] = useState<any>(null);
  const [selectedCharacter, setSelectedCharacter] = useState<any>(null);
  const [showDetail, setShowDetail] = useState<boolean>(false);

  // 加载人物关系数据
  const { data, loading, error } = useDataLoader<any>(() => {
    return fetch('/data/character_network.json')
      .then(response => {
        if (!response.ok) {
          throw new Error('无法加载人物关系数据');
        }
        return response.json();
      });
  });

  useEffect(() => {
    if (data) {
      setCharacterData(data);
    }
  }, [data]);

  // 处理角色选择
  const handleSelectCharacter = (characterId: string) => {
    if (characterData && characterData.characters) {
      const character = characterData.characters.find((c: any) => c.id === characterId);
      if (character) {
        setSelectedCharacter(character);
        setShowDetail(true);
      }
    }
  };

  // 关闭详情
  const handleCloseDetail = () => {
    setShowDetail(false);
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="text-center">
          <div className="spinner-border text-primary" role="status">
            <span className="sr-only">加载中...</span>
          </div>
          <p className="mt-2">正在加载人物关系数据...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
        <strong className="font-bold">加载失败！</strong>
        <span className="block sm:inline"> {error.message}</span>
      </div>
    );
  }

  if (!characterData) {
    return <div>没有找到人物关系数据</div>;
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold mb-6">《凡人修仙传》人物关系网络</h1>

      <div className="bg-white rounded-lg shadow-md p-6 mb-8">
        <p className="text-gray-700 mb-6">
          探索《凡人修仙传》中主要人物之间的复杂关系网络。点击人物节点可查看详细信息，
          不同颜色的连线代表不同类型的关系。韩立作为主角，位于网络的中心位置。
        </p>

        <div className="mb-6">
          <h2 className="text-xl font-semibold mb-3">关系类型说明</h2>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {characterData.relationshipTypes.map((type: any, index: number) => (
              <div key={index} className="flex items-center">
                <div 
                  className="w-4 h-4 rounded-full mr-2" 
                  style={{ backgroundColor: type.color }}
                ></div>
                <span>{type.type}: {type.description}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="relative">
          {/* 人物关系网络图 */}
          <CharacterNetwork 
            data={characterData} 
            onSelectCharacter={handleSelectCharacter}
            height="700px"
          />

          {/* 人物详情弹窗 */}
          {showDetail && selectedCharacter && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
              <div className="max-w-2xl w-full max-h-[90vh] overflow-auto">
                <CharacterDetail 
                  character={selectedCharacter} 
                  relationshipTypes={characterData.relationshipTypes}
                  onClose={handleCloseDetail} 
                />
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-md p-6 mb-8">
        <h2 className="text-2xl font-semibold mb-4">主要人物介绍</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {characterData.characters.map((character: any, index: number) => (
            <div 
              key={index} 
              className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow cursor-pointer"
              onClick={() => handleSelectCharacter(character.id)}
            >
              <div className="flex items-center mb-3">
                <div className="w-12 h-12 rounded-full bg-blue-100 flex-shrink-0 overflow-hidden">
                  {character.avatar ? (
                    <img 
                      src={`/images/characters/${character.avatar}`} 
                      alt={character.name}
                      className="w-full h-full object-cover" 
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-blue-500 font-bold">
                      {character.name.charAt(0)}
                    </div>
                  )}
                </div>
                <div className="ml-3">
                  <h3 className="font-bold text-lg">{character.name}</h3>
                  <p className="text-sm text-gray-600">{character.title}</p>
                </div>
              </div>
              <p className="text-gray-700 text-sm line-clamp-3">{character.description}</p>
              <div className="mt-3 text-sm text-blue-600">点击查看详情</div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-semibold mb-4">修仙境界体系</h2>
        <div className="overflow-x-auto">
          <table className="min-w-full bg-white">
            <thead>
              <tr>
                <th className="py-2 px-4 border-b border-gray-200 bg-gray-50 text-left">境界</th>
                <th className="py-2 px-4 border-b border-gray-200 bg-gray-50 text-left">代表人物</th>
              </tr>
            </thead>
            <tbody>
              {characterData.cultivationRanks.map((rank: string, index: number) => {
                const charactersInRank = characterData.characters.filter(
                  (c: any) => c.cultivation === rank
                );

                return (
                  <tr key={index} className={index % 2 === 0 ? 'bg-gray-50' : 'bg-white'}>
                    <td className="py-2 px-4 border-b border-gray-200 font-medium">{rank}</td>
                    <td className="py-2 px-4 border-b border-gray-200">
                      {charactersInRank.length > 0 
                        ? charactersInRank.map((c: any) => c.name).join(', ')
                        : '暂无数据'
                      }
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CharacterNetworkPage;
